import { align } from "./img.js";
export default [
    {
        name: 'replace',
        icon: 'video',
        tooltip: 'Replace',
        popup: (editor, target, close) => target
            ? editor.e.fire('generateReplaceVideoTabs', target, close)
            : undefined
    },
    {
        name: 'bin',
        tooltip: 'Delete',
        exec: (editor, image) => {
            image && editor.s.removeNode(image);
        }
    },
    {
        name: 'pencil',
        tooltip: 'Edit',
        exec: (editor, target) => {
            target && editor.e.fire('openVideoProperties', target);
        }
    },
    align
];
